*{box-sizing:border-box}body{margin:0;font-family:system-ui;background:#07111b;color:#eef6ff}body.light{background:#eef3f8;color:#14202d}.app{min-height:100vh;display:grid;grid-template-columns:56px 270px 1fr 250px}.dock,.side,.right,header,footer{background:#0b1723;border-color:#22384b}.dock{display:flex;flex-direction:column;align-items:center;gap:8px;padding:10px;border-right:1px solid #22384b}.brand{width:38px;height:38px;border-radius:12px;display:grid;place-items:center;background:linear-gradient(135deg,#2f8cff,#00c2ff);font-weight:800}.dock button{width:40px;height:40px}.dock #theme{margin-top:auto}.side,.right{padding:14px;border-right:1px solid #22384b}.right{border-right:0;border-left:1px solid #22384b}button,input{font:inherit;border:1px solid #22384b;background:#12273a;color:inherit;border-radius:10px;padding:8px}.side input,.palette input{width:100%}.tree{padding:8px;border-radius:8px;color:#9db0c3}.tree:hover{background:#12273a;color:white}main{display:grid;grid-template-rows:56px 42px 1fr 26px;min-width:0}header{display:flex;align-items:center;justify-content:space-between;padding:0 14px;border-bottom:1px solid #22384b}.tabs{display:flex;gap:6px;padding:6px;background:#0f2030;border-bottom:1px solid #22384b}.tab{padding:7px 10px;border:1px solid #22384b;border-radius:9px;background:#0b1723}.tab.active{border-color:#4aa3ff}#view{padding:18px;overflow:auto}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card{background:#0b1723;border:1px solid #22384b;border-radius:16px;padding:16px}.metric{font-size:30px;font-weight:800}.reader{max-width:850px;margin:auto}.reader pre{background:#02070d;padding:14px;border-radius:12px;overflow:auto}footer{display:flex;gap:18px;align-items:center;padding:0 10px;font-size:12px;background:#0d4d7a}.palette{position:fixed;top:10%;left:50%;transform:translateX(-50%);width:min(720px,92vw);background:#0b1723;border:1px solid #22384b;border-radius:16px;padding:12px;z-index:50;box-shadow:0 20px 60px #0008}.result{padding:12px;border-bottom:1px solid #22384b}.hidden{display:none}@media(max-width:1100px){.app{grid-template-columns:56px 230px 1fr}.right{display:none}}@media(max-width:760px){.app{grid-template-columns:56px 1fr}.side{display:none}.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:520px){.app{grid-template-columns:1fr}.dock{position:fixed;bottom:0;left:0;right:0;height:58px;z-index:10;flex-direction:row;justify-content:space-around}.brand,#theme{display:none!important}main{padding-bottom:58px}.grid{grid-template-columns:1fr}}
